package dev.levilainpetit.wux.wallpaper

import android.graphics.Bitmap
import android.graphics.BitmapFactory
import java.util.Base64

/**
 * Le Vault Boy de Fallout, pouce levé, dans son anneau : un masque PNG
 * (400 × 391, blanc et alpha) tiré d'une capture, l'anneau effacé là où il
 * passe derrière lui. Allumé comme dans le jeu : la silhouette brille, les
 * traits restent sombres. Usage personnel : l'application n'est pas
 * distribuée.
 */
internal object VaultBoy {

    /** Le centre et le rayon de l'anneau, en fractions de la largeur et de la hauteur de l'image. */
    const val RING_X = 0.5814f
    const val RING_Y = 0.5743f
    const val RING_R = 0.4118f

    /** Le masque, en ALPHA_8 : la couleur vient de la peinture. */
    val mask: Bitmap by lazy {
        val bytes = Base64.getDecoder().decode(PNG.joinToString(""))
        val image = BitmapFactory.decodeByteArray(bytes, 0, bytes.size)!!
        image.extractAlpha().also { image.recycle() }
    }

    private val PNG = listOf(
        "",
        "",
        "",
        "",
    )
}
